}/* Pile is a chronological page of notes; its next line follows the last thought. */
.ds-thought{
  margin: 0 0 28px;
}.ds-thought-text,.ds-thought-input textarea{
  font: var(--writing-size,18px)/1.8 var(--writing-font,-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  color: var(--text, #35312d);
  margin: 0;
}.ds-thought-meta{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 25px;
  margin-top: 5px;
  font-size: 11px;
  color: var(--muted, #696057);
  opacity: 0;
  transition: opacity 160ms;
}.ds-thought:hover .ds-thought-meta,.ds-thought:focus-within .ds-thought-meta{
  opacity: 1;
}.ds-thought-actions{
  display: flex;
  gap: 5px;
}.ds-thought-actions button{
  padding: 4px 8px;
  border-radius: var(--radius-control, 999px);
  font-size: 11px;
}.ds-thought-input{
  display: flex;
  align-items: flex-start;
  gap: 16px;
}.ds-thought-input textarea{
  display: block;
  min-width: 0;
  flex: 1;
  border: 0;
  background: none;
  padding: 0;
  min-height: 33px;
  resize: none;
  overflow: hidden;
}.ds-add-thought-button{
  flex-shrink: 0;
  height: 30px;
  padding: 0 13px;
  margin-top: 2px;
  border-radius: var(--radius-control, 999px);
  background: var(--field, #efebe5);
  font-size: 12px;
}.ds-add-thought-button:disabled{
  visibility: hidden;
